5	import { version as currentVersion } from '../version';
6	
7	import { Module, API } from '../index';
8	
9	export interface Version {
10	  version: string;
11	  info?: string;
12	  [key: string]: any;
13	}
14	
15	export interface UnknownEntries {
16	  [key: string]: {
17	    [key: string]: any;
18	  };
19	}
20	
21	export interface Versions {
22	  latest?: Version;
23	  next?: Version;
24	  current?: Version;
25	}
26	
27	export interface SubState {
28	  versions: Versions & UnknownEntries;
29	  lastVersionCheck: number;
30	  dismissedVersionNotification: undefined | string;
31	}
32	
33	const checkInterval = 24 * 60 * 60 * 1000;
34	const versionsUrl = 'https://storybook.js.org/versions.json';
35	
36	async function fetchLatestVersion(v: string) {
37	  const fromFetch = await fetch(`${versionsUrl}?current=${v}`);
38	  return fromFetch.json();
39	}
40	
41	export interface SubAPI {
42	  getCurrentVersion: () => Version;
43	  getLatestVersion: () => Version;
44	  versionUpdateAvailable: () => boolean;
45	}
46	
47	export default function({ store, mode }: Module) {
48	  const {
49	    versions: persistedVersions = {},
50	    lastVersionCheck = 0,
51	    dismissedVersionNotification,
52	  } = store.getState();
53	
54	  // Check to see if we have info about the current version persisted
55	  const persistedCurrentVersion = Object.values(persistedVersions).find(
56	    v => v.version === currentVersion
57	  );
58	  const state = {
59	    versions: {
60	      ...persistedVersions,
61	      current: {
62	        version: currentVersion,
63	        ...(persistedCurrentVersion && { info: persistedCurrentVersion.info }),
64	      },
65	    },
66	    lastVersionCheck,
67	    dismissedVersionNotification,
68	  };
69	
70	  const api: SubAPI = {
71	    getCurrentVersion: () => {
72	      const {
73	        versions: { current },
74	      } = store.getState();
75	      return current;
76	    },
77	    getLatestVersion: () => {
78	      const {
79	        versions: { latest, next, current },
80	      } = store.getState();
81	      if (current && semver.prerelease(current.version) && next) {
82	        return latest && semver.gt(latest.version, next.version) ? latest : next;
83	      }
84	      return latest;
85	    },
86	    versionUpdateAvailable: () => {
87	      const latest = api.getLatestVersion();
88	      const current = api.getCurrentVersion();
89	
90	      if (!latest || !latest.version) {
91	        return true;
92	      }
93	      return latest && semver.gt(latest.version, current.version);
94	    },
95	  };
96	
97	  // Grab versions from the server/local storage right away
98	  async function init({ api: fullApi }: API) {
99	    const { versions = {} } = store.getState();
100	
101	    const now = Date.now();
102	    if (!lastVersionCheck || now - lastVersionCheck > checkInterval) {
103	      try {
104	        const { latest, next } = await fetchLatestVersion(currentVersion);
105	        await store.setState(
106	          {
107	            versions: { ...versions, latest, next },
108	            lastVersionCheck: now,
109	          },
110	          { persistence: 'permanent' }
111	        );
112	      } catch (error) {
113	        logger.warn(`Failed to fetch latest version from server: ${error}`);
114	      }
115	    }
116	
117	    if (api.versionUpdateAvailable()) {
118	      const latestVersion = api.getLatestVersion().version;
119	
120	      if (
121	        latestVersion !== dismissedVersionNotification &&
122	        !semver.patch(latestVersion) &&
123	        !semver.prerelease(latestVersion) &&
124	        mode !== 'production'
125	      ) {
126	        fullApi.addNotification({
127	          id: 'update',
128	          link: '/settings/about',
129	          content: `🎉 Storybook ${latestVersion} is available!`,
130	          onClear() {
131	            store.setState(
132	              { dismissedVersionNotification: latestVersion },
133	              { persistence: 'permanent' }
134	            );
135	          },
136	        });
137	      }
138	    }
139	  }
140	
141	  return { init, state, api };
142	}
