jest.mock('./version', () => ({
  version: '3.0.0',
}));

jest.mock('global', () => ({
  VERSIONCHECK: JSON.stringify({
    success: true,
    data: {
      latest: { version: '4.0.0' },
      next: { version: '4.1.0-alpha.0' },
    },
    time: 1,
  }),
}));

jest.mock('@storybook/client-logger');

function createMockStore() {
  let state = {};
  return {
    getState: jest.fn().mockImplementation(() => state),
    setState: jest.fn().mockImplementation(s => {
      state = { ...state, ...s };
    }),
  };
}

describe('build-time versions', () => {
  it('initial state populated from VERSIONCHECK', () => {
    const store = createMockStore();
    const { state } = initVersions({ store });
    expect(state.versions.current).toEqual({ version: '3.0.0' });
    expect(state.versions.latest).toEqual({ version: '4.0.0' });
    expect(state.versions.next).toEqual({ version: '4.1.0-alpha.0' });
  });

  it('getCurrentVersion / getLatestVersion', () => {
    const store = createMockStore();
    const { api, state } = initVersions({ store });
    store.setState(state);
    expect(api.getCurrentVersion()).toEqual({ version: '3.0.0' });
    expect(api.getLatestVersion()).toEqual({ version: '4.0.0' });
  });

  it('versionUpdateAvailable: minor/major -> true', () => {
    const store = createMockStore();
    const { api, state } = initVersions({ store });
    store.setState(state);
    expect(api.versionUpdateAvailable()).toEqual(true);
  });

  it('versionUpdateAvailable: same -> false', () => {
    const store = createMockStore();
    const { api, state } = initVersions({ store });
    state.versions.latest = { version: '3.0.0' };
    store.setState(state);
    expect(api.versionUpdateAvailable()).toEqual(false);
  });

  it('versionUpdateAvailable: patch -> false', () => {
    const store = createMockStore();
    const { api, state } = initVersions({ store });
    state.versions.latest = { version: '3.0.1' };
    store.setState(state);
    expect(api.versionUpdateAvailable()).toEqual(false);
  });

  it('versionUpdateAvailable: prerelease latest -> false', () => {
    const store = createMockStore();
    const { api, state } = initVersions({ store });
    state.versions.latest = { version: '4.0.0-alpha.0' };
    state.versions.next = undefined;
    store.setState(state);
    expect(api.versionUpdateAvailable()).toEqual(false);
  });

  it('versionUpdateAvailable: no latest -> false', () => {
    const store = createMockStore();
    const { api, state } = initVersions({ store });
    state.versions.latest = undefined;
    state.versions.next = undefined;
    store.setState(state);
    expect(api.versionUpdateAvailable()).toEqual(false);
  });

  it('versionUpdateAvailable: prerelease current stripped vs stable latest -> true', () => {
    const store = createMockStore();
    const { api, state } = initVersions({ store });
    state.versions.current.version = '3.1.0-alpha.0';
    state.versions.latest = { version: '4.0.0' };
    state.versions.next = undefined;
    store.setState(state);
    expect(api.versionUpdateAvailable()).toEqual(true);
  });

  it('notification added for minor/major when not dismissed & not production', () => {
    const store = createMockStore();
    const { api, init, state } = initVersions({ store });
    store.setState(state);
    const addNotification = jest.fn();
    return init({ api: { addNotification, ...api } }).then(() => {
      expect(addNotification).toHaveBeenCalled();
    });
  });

  it('no notification in production', () => {
    const store = createMockStore();
    const { api, init, state } = initVersions({ store, mode: 'production' });
    store.setState(state);
    const addNotification = jest.fn();
    return init({ api: { addNotification, ...api } }).then(() => {
      expect(addNotification).not.toHaveBeenCalled();
    });
  });

  it('no notification when dismissed; onClear persists', () => {
    const store = createMockStore();
    const { api, init, state } = initVersions({ store });
    store.setState(state);
    store.setState({ dismissedVersionNotification: '4.0.0' });
    const addNotification = jest.fn();
    return init({ api: { addNotification, ...api } }).then(() => {
      expect(addNotification).not.toHaveBeenCalled();
    });
  });

  it('onClear persists dismissed version', () => {
    const store = createMockStore();
    const { api, init, state } = initVersions({ store });
    store.setState(state);
    let notification;
    const addNotification = jest.fn().mockImplementation(n => {
      notification = n;
    });
    return init({ api: { addNotification, ...api } }).then(() => {
      notification.onClear();
      expect(store.setState).toHaveBeenCalledWith(
        { dismissedVersionNotification: '4.0.0' },
        { persistence: 'permanent' }
      );
    });
  });
});
